import{r as e}from"./rolldown-runtime-BLXQ4ufn.js";import{t}from"./jsx-runtime-DsDUoChv.js";import{t as n}from"./configuration-C-DRFSPK.js";var r=e(t()),i={title:`Instance Types`,description:`Declare instance types in descriptor files - components, runtime, install parameters, install and update steps, placeholders, server roles, management operations, discovery, and types a backend provides.`,icon:`Boxes`},a={contents:[{heading:void 0,content:"An extension adds instance types through descriptor files. Every `.toml` or `.json` file the manifest's `contributes.instanceTypes` glob matches is one type, whose id is `<extension id>:<name>`, such as `com.example.llama:llama-server`. Users choose these types in a new installation, and the application installs, starts, and manages their instances as the descriptor says."},{heading:void 0,content:"A descriptor decodes tolerantly: an unknown field is ignored, but an unknown step kind, readiness, or runtime is refused. Everything is checked at registration; each problem is reported with its place (such as `servers[1].command[0]`, or a line and column), the type is not registered, and the extension does not install."},{heading:`a-complete-example`,content:'A JSON descriptor uses the same keys, such as `"displayName"` and `"install": { "parameters": [...], "steps": [...] }`.'},{heading:`top-level-keys`,content:`Key`},{heading:`top-level-keys`,content:`Required`},{heading:`top-level-keys`,content:`Description`},{heading:`top-level-keys`,content:"`name`"},{heading:`top-level-keys`,content:`Yes`},{heading:`top-level-keys`,content:"The type name, of `a-z`, `0-9`, `.`, `-`; the type id is `<extension id>:<name>`"},{heading:`top-level-keys`,content:"`provider`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:"`declarative` (the default) or `backend` (see Types a backend provides)"},{heading:`top-level-keys`,content:"`displayName`"},{heading:`top-level-keys`,content:`Yes`},{heading:`top-level-keys`,content:`The display name; see Text`},{heading:`top-level-keys`,content:"`defaultName`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:'Plain-text prefix for generated instance names, for example `"llama.cpp"`. When the user leaves the name empty, the host adds a random suffix. It trims the prefix and ignores a blank value.'},{heading:`top-level-keys`,content:"`description`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:`A description; see Text`},{heading:`top-level-keys`,content:"`preview`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:"The preview image: a file of the package, such as `images/preview.png`"},{heading:`top-level-keys`,content:"`attachOnly`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:"`true`: an instance only comes from discovery attaching an existing installation; the type is not offered for creation, and creating or importing one by hand is refused"},{heading:`top-level-keys`,content:"`components`"},{heading:`top-level-keys`,content:`Yes`},{heading:`top-level-keys`,content:'The instance\'s component directory names; must include `core`; each of `a-z`, `0-9`, `-`, none repeated; an entry may be `{ name = "node", label = … }` to show a text instead of the name'},{heading:`top-level-keys`,content:"`environment`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:"`path` and `vars` for its processes; see Environment"},{heading:`top-level-keys`,content:"`runtime`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:'The runtime; `{ kind = "none" }` by default'},{heading:`top-level-keys`,content:"`install`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:"`parameters` (the install form) and `steps` (the install steps)"},{heading:`top-level-keys`,content:"`update`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:"`steps`: a ready instance's update steps"},{heading:`top-level-keys`,content:"`servers`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:`The server roles`},{heading:`top-level-keys`,content:"`management`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:"`operations`: the management operations its instances offer; `adopts`: the built-in type whose management they take (below)"},{heading:`top-level-keys`,content:"`discovery`"},{heading:`top-level-keys`,content:`No`},{heading:`top-level-keys`,content:`Signatures that recognize existing installations; see Discovery`},{heading:`components`,content:'A component may set `defaultPath = "assets/weights"` to place it below the install root. Explicit component locations take precedence. Set `[terminal].cwd` to a component path such as `"{component.core}/tools"` for an instance terminal that opens in the CLI directory. The default is the core directory.'},{heading:`components`,content:"Components are the instance's directories. By default each one is a subdirectory of the install directory with its own name, `<install dir>/<name>`; users may place a component elsewhere when they create the instance. Steps and commands refer to a component with `{component.<name>}` and never write a path. `core` always exists, and server processes run in it."},{heading:`components`,content:`To let users reuse an existing installation, declare which component can point to it. For example, this type can use an existing Node.js directory:`},{heading:`components`,content:"A newly created instance owns its components. When the user selects an external directory in **Paths**, the host checks that the directory and the optional platform-specific executable exist. Discovery can also mark components external during import. The managed `python` component always belongs to the instance."},{heading:`components`,content:"Deleting or reinstalling the instance preserves external directories. The host refuses `git-clone`, `unpack` and `download` with `unpackTo` anywhere inside one. File downloads, `write-file` and `git-pull` can still modify its contents. A backend planning a `run` step should check the component's `external` flag before asking its own program to change files."},{heading:`components`,content:"A component can declare `rebuildable`. This example offers a Node.js rebuild switch and hides the Core switch. By default, only `core` and `python` offer switches. Each switch starts off and applies to one install. External directories cannot be rebuilt."},{heading:`runtime`,content:`Form`},{heading:`runtime`,content:`Description`},{heading:`runtime`,content:'`{ kind = "none" }`'},{heading:`runtime`,content:`No runtime (the default)`},{heading:`runtime`,content:'`{ kind = "python", version = "3.11" }`'},{heading:`runtime`,content:"The application's managed Python; the version must be one the application installs (`3.10` to `3.15`), and `python` must be a declared component"},{heading:`runtime`,content:'`{ kind = "system-binary", name = "node" }`'},{heading:`runtime`,content:"A program on the system; `name` is a program name without a path separator"},{heading:`text`,content:"`displayName`, `description`, a component's `label`, and a parameter's `label`, `help`, `disabledReason`, and option labels are written as:"},{heading:`text`,content:'plain text, `"llama.cpp server"`, the same in every language;'},{heading:`text`,content:'text by language, `{ en = "…", zh = "…" }`;'},{heading:`text`,content:"a text key, `{ key = \"ext.<extension id>.<key>\" }`, read from the extension's text files (see Interface). The key must start with the extension's own `ext.<extension id>.`; a key of the application or of another extension is an error."},{heading:`install-parameters`,content:"Each `[[install.parameters]]` entry is a field of the install form, shown in one group when an instance is created. An instance's parameter values are its spec."},{heading:`install-parameters`,content:`Key`},{heading:`install-parameters`,content:`Description`},{heading:`install-parameters`,content:"`name`"},{heading:`install-parameters`,content:"Required; of `A-Z`, `a-z`, `0-9`, `_`, `-`, not repeated; placeholders refer to it as `{param.<name>}`"},{heading:`install-parameters`,content:"`kind`"},{heading:`install-parameters`,content:"Required: `text`, `number`, `boolean`, `select`, `multiselect`, `path`, `secret`, `slider`, `textarea`"},{heading:`install-parameters`,content:"`label`"},{heading:`install-parameters`,content:"The label; `name` when absent"},{heading:`install-parameters`,content:"`help`"},{heading:`install-parameters`,content:`Help text`},{heading:`install-parameters`,content:"`required`"},{heading:`install-parameters`,content:"Whether it must have a value; `false` by default"},{heading:`install-parameters`,content:"`default`"},{heading:`install-parameters`,content:`The default, a value the field takes`},{heading:`install-parameters`,content:"`options`"},{heading:`install-parameters`,content:'Required for `select` and `multiselect`: a list of values, or of `{ value = "…", label = … }`; no value twice'},{heading:`install-parameters`,content:"`min`, `max`, `step`"},{heading:`install-parameters`,content:"A number's bounds and step; `min` not above `max`, `step` positive; a `slider` needs both `min` and `max`"},{heading:`install-parameters`,content:"`path`"},{heading:`install-parameters`,content:"Whether a `path` field picks a `directory` (the default) or a `file`"},{heading:`install-parameters`,content:"`advanced`"},{heading:`install-parameters`,content:`It has a working default, so the creation form collapses it`},{heading:`install-parameters`,content:"`visibleWhen`"},{heading:`install-parameters`,content:`Shown only while the condition holds; a hidden field keeps no value`},{heading:`install-parameters`,content:"`requiredWhen`"},{heading:`install-parameters`,content:`Required while the condition holds`},{heading:`install-parameters`,content:"`disabledWhen`"},{heading:`install-parameters`,content:"Disabled while the condition holds, with `disabledReason` saying why"},{heading:`install-parameters`,content:'A condition is `{ key = "<field>", equals = <value> }`, or several combined with `{ any = [...] }` or `{ all = [...] }`, and reads only declared fields.'},{heading:`install-parameters`,content:`The values are read once, where they enter the application:`},{heading:`install-parameters`,content:`a field the type does not declare is refused in a request, and dropped from a saved spec;`},{heading:`install-parameters`,content:"each value must be its field's kind: a number within its bounds and on its step, a `select` one of its options, a `multiselect` a list of them;"},{heading:`install-parameters`,content:"`null`, empty text, and an empty list are no value, and the default applies;"},{heading:`install-parameters`,content:"a field whose `visibleWhen` does not hold loses its value; a field that is required (or whose `requiredWhen` holds) and shown, without a value, is refused."},{heading:`install-parameters`,content:"A `secret` field only hides its input on screen. Its value is stored as text with the other\nparameters, in the instance's record."},{heading:`placeholders`,content:`Placeholders are replaced as text when a step or command runs; there is no expression language:`},{heading:`placeholders`,content:`Placeholder`},{heading:`placeholders`,content:`Value`},{heading:`placeholders`,content:`Where`},{heading:`placeholders`,content:"`{component.<name>}`"},{heading:`placeholders`,content:`A declared component's directory`},{heading:`placeholders`,content:`Steps, server commands and environments`},{heading:`placeholders`,content:"`{param.<name>}`"},{heading:`placeholders`,content:`A declared parameter's value; a list joined with commas, empty when unset`},{heading:`placeholders`,content:`Steps, server commands and environments`},{heading:`placeholders`,content:"`{instance.id}`"},{heading:`placeholders`,content:`The instance's id`},{heading:`placeholders`,content:`Steps, server commands and environments`},{heading:`placeholders`,content:"`{instance.root}`"},{heading:`placeholders`,content:`The instance's install directory`},{heading:`placeholders`,content:`Steps, server commands and environments`},{heading:`placeholders`,content:"`{port}`"},{heading:`placeholders`,content:`The port the server was given`},{heading:`placeholders`,content:"A server's `command` and `env` only"},{heading:`placeholders`,content:"`{endpoint.<role>}`"},{heading:`placeholders`,content:"Ready base URL of an instance role listed in this role’s `after`"},{heading:`placeholders`,content:"A server’s `command` and `env` only"},{heading:`placeholders`,content:"`{extension.root}`"},{heading:`placeholders`,content:`The extension's package directory (a development link's folder)`},{heading:`placeholders`,content:`Steps, server commands and environments`},{heading:`placeholders`,content:"`{host.python}`"},{heading:`placeholders`,content:`The application's managed Python, the one Python backends run on`},{heading:`placeholders`,content:`Steps, server commands and environments`},{heading:`placeholders`,content:"`{{` and `}}` are literal braces. An undeclared component or parameter, `{port}` anywhere else, and an unclosed `{` are errors at registration."},{heading:`placeholders`,content:"`{extension.root}` locates package files. Use a component path for a step's output. When a `run` step's or a server's program is `{host.python}`, it runs with the application's `sd_webui_all_in_one` importable (the launcher code first on `PYTHONPATH`) and `PYTHONUTF8`, `PYTHONUNBUFFERED` and `PYTHONNOUSERSITE` set to `1`. Resolving the interpreter waits while App Runtime prepares it. If preparation has failed, the operation returns the runtime's error."},{heading:`placeholders`,content:"**Step paths** (`to`, `unpackTo`, `archive`, `into`, `dir`, `cwd` and `path`) start with `{component.<name>}`, optionally followed by `/` and a path inside the component, such as `{component.core}/bin/server`. A step whose resolved path would leave its component is refused. Entries in `environment.path` may also start with `{instance.root}`."},{heading:`steps`,content:'`[[install.steps]]` run for initial installation and retry. To give explicit reinstallation its own plan, declare `[[reinstall.steps]]`; otherwise it follows the installation plan. Each step may have a localized title, e.g. `title = { en = "Build model index", zh = "生成模型索引" }`. The workspace shows the title while running and retains it on failure. For static types, `[[update.steps]]` run when a ready instance is updated (`install.steps` when none are declared). They run in order, and the first that fails fails the operation. The install progress names the current step and counts the finished ones.'},{heading:`steps`,content:"`kind`"},{heading:`steps`,content:`Keys`},{heading:`steps`,content:`Description`},{heading:`steps`,content:"`download`"},{heading:`steps`,content:"`url`, `sha256`, and one of `to` or `unpackTo`"},{heading:`steps`,content:"Downloads through the application's proxy, trying the configured GitHub mirror first for a `https://github.com/...` URL. `sha256` is required: 64 hex digits, or a parameter; a mismatch replaces nothing. `to` keeps the file, `unpackTo` unpacks it into a directory, with an optional `strip` as `unpack`"},{heading:`steps`,content:"`unpack`"},{heading:`steps`,content:"`archive`, `into`, optional `strip`"},{heading:`steps`,content:"Unpacks a zip or tar (gz, xz, bz2); an entry or link that would leave the target is refused; into an existing directory, entries of the same name are replaced and the rest kept. `strip = N` drops the first `N` path components of every entry (an archive's top directory with `1`); a file with nothing left, or two entries that strip to one name, are refused. A tar's symbolic link may point up with leading `..` (as Node.js's `bin/npm -> ../lib/...`), but not out of what `strip` keeps"},{heading:`steps`,content:"`git-clone`"},{heading:`steps`,content:"`url`, `into`, optional `branch`"},{heading:`steps`,content:"Clones with the application's Git; a repository already there is left for `git-pull`"},{heading:`steps`,content:"`git-pull`"},{heading:`steps`,content:"`dir`"},{heading:`steps`,content:`Pulls an existing repository`},{heading:`steps`,content:"`run`"},{heading:`steps`,content:"`command`, optional `cwd` (`{component.core}` by default) and `env`"},{heading:`steps`,content:"Runs a program directly (no shell), the program first in `command`; its output goes to the task, and a failure carries its last 4 KiB"},{heading:`steps`,content:"`python-env`"},{heading:`steps`,content:`none`},{heading:`steps`,content:"Prepares the managed Python in the `python` component; later `run` steps find it first on `PATH`. Only for a Python runtime"},{heading:`steps`,content:"`write-file`"},{heading:`steps`,content:"`path`, `content`"},{heading:`steps`,content:`Writes a file; refused when the target's directory resolves outside its component`},{heading:`steps`,content:"`probe`"},{heading:`steps`,content:"`url`, optional `timeoutSeconds` (60 by default)"},{heading:`steps`,content:"Waits for a 2xx answer from a loopback `http://` URL (`127.0.0.1`, `localhost`, or `[::1]`)"},{heading:`steps`,content:"`unpack` and `download` with `unpackTo` also accept `replace = true`. Use it when an update archive should remove files left by the old version. The host extracts beside the target and swaps in the completed directory. It refuses replacement if the target contains another instance component. Without `replace`, unpacking into an existing directory keeps unrelated entries."},{heading:`servers`,content:"Each `[[servers]]` entry is a server role. Starting a declarative instance means starting its servers in order."},{heading:`servers`,content:`Key`},{heading:`servers`,content:`Description`},{heading:`servers`,content:"`role`"},{heading:`servers`,content:"Required: 1 to 64 characters of `a-z`, `0-9`, `-`; `control` is the management API (below)"},{heading:`servers`,content:"`command`"},{heading:`servers`,content:"The program and its arguments. A backend-provided type may omit this to call `provider.launchPlan` for this role."},{heading:`servers`,content:"`env`"},{heading:`servers`,content:`Environment variables; values may use placeholders`},{heading:`servers`,content:"`port`"},{heading:`servers`,content:'`{ allocate = true }` (the default), `{ fixed = 8080 }`, `{ param = "<numeric install field>" }`, or `{ launch = "<numeric launch field>" }`'},{heading:`servers`,content:"`readiness`"},{heading:`servers`,content:'Required for every role but `control`. Choose one of `{ http = "/health" }` (an absolute path), `{ tcp = true }`, `{ stdout = "<regex>" }` or `{ captured = true }`. Optional `timeoutSeconds` defaults to 120.'},{heading:`servers`,content:"`after`"},{heading:`servers`,content:`The roles it starts after; only declared roles, with no cycle`},{heading:`servers`,content:"`restart`"},{heading:`servers`,content:"`never` (the default) or `on-failure` (restarted automatically within a limit)"},{heading:`servers`,content:"`webview`"},{heading:`servers`,content:"When `true`, the running role's address is offered as a page in the WebUI tab; `false` by default"},{heading:`servers`,content:"`required`"},{heading:`servers`,content:"`true` by default. A required role that fails fails the start; an optional one that fails leaves the instance running degraded"},{heading:`servers`,content:"A server process runs in the `core` component. The variables in `env` are merged with the instance's environment variables, and the instance's win on a name both set."},{heading:`servers`,content:'For a UI hosted below the root, set `webview = true` and\n`webviewPath = "/dashboard/"`. The readiness probe may use a separate path. Set `externalBrowserPath = "/studio"` to choose a different same-origin page for the title bar browser button.\nA role with `after = ["api"]` can pass `{endpoint.api}` in its command or\nenvironment. It resolves at start to the running API role\'s base URL, including\nthe allocated port.'},{heading:`servers`,content:'Use `readiness = { captured = true }` for a server that chooses its own browser URL, for example one that includes a session token in the query. The host gives each start a fresh runtime broker session. The program reports its loopback HTTP(S) URL with a `browser.open` event. With `sd_webui_all_in_one`, create the client with `DesktopBrokerClient.from_env()` and call `emit_event("browser.open", {"url": url})` on it. The first accepted URL makes the role ready, and `webview = true` opens that URL with its query intact. Printing a URL to stdout alone leaves this probe waiting until timeout.'},{heading:`the-management-api`,content:"A type with a Python runtime may also run the application's management API, the control server every built-in WebUI runs, on the instance's own Python. Declare the `control` role with nothing but `after` and `required`, and order your own roles after it:"},{heading:`the-management-api`,content:"The application then starts it before your roles, shows the instance's Management API in its information and in Settings → API Servers, and keeps it running while the instance is managed or launched. Stopping or restarting it does not stop your roles. A type without a Python runtime cannot declare `control`, and the error says why. The role alone adds no management section; a type takes the built-in WebUIs' versions, extensions, models, and PyTorch sections by adopting a built-in type's management."},{heading:`the-management-api`,content:'Declare per-instance launch fields in `[[launch.parameters]]` using install parameter syntax. Users edit them under **Launch**; the next service start reads them without reinstalling. Use `{launch.name}` in a server command or environment. A server may set `cwd = "{component.core}/service"`. The default working directory is `core`. Backend launch plans receive `launchValues` alongside the install `values`.'},{heading:`the-management-api`,content:"Set `preflight = true` under `[launch]` to check the whole instance once before starting its roles. The host sends `provider.launchPreflight` with `type`, `instance`, install `values` and effective `launchValues`. Return `{}` on success or an RPC error with a reason. For example, the greeter checks that the selected greeting file still exists. Role restarts do not repeat this check."},{heading:`the-management-api`,content:'A launch field with `kind = "select"` may set `optionsSource = "models"` when its extension has a backend. Opening Launch for this instance requests its choices from `provider.launchOptions`. For example, return `{ "options": { "models": ["a.gguf", "b.gguf"] } }`. The management tool `get_instance_launch_options` lists the nonsecret choices for this instance by field key. Static options remain available. The host checks a newly selected dynamic value on save. A saved value can be kept when the backend is offline or the model has disappeared.'},{heading:`the-management-api`,content:'Type-level `quickPaths = [{ name = "Outputs", component = "core", path = "output" }]` seeds Overview when an instance is created or imported, including discovery. Users may rename, reorder or remove those shortcuts. Moving an instance also moves shortcut targets inside the old root. Set a type\'s top-level `migrationNotice` to localized text to tell users, in the migration preview, about paths stored by your program that may need attention.'},{heading:`environment`,content:"`[environment]` applies to the type's `run` steps, its servers, and its terminal:"},{heading:`environment`,content:"`unset` removes inherited variables by exact name or by prefix with a trailing `*`. Windows matches variable names without regard to case. An explicitly supplied variable can set the name again. The instance's own variables take precedence over `vars` and a step's or server's `env`. Each `path` entry starts at a component or the instance root. Use `{port}` only in the role's command or environment."},{heading:`management-operations`,content:"`[management] operations` lists the management operations an instance offers beyond the standard lifecycle. A declarative type can declare `update` and `terminal`. With `update`, updating a ready instance runs `update.steps` (or `install.steps`); without it, its instances cannot be updated. With `terminal`, its instances offer a terminal in `core` with the type's environment."},{heading:`read-only-model-component`,content:'Add a component such as `weights` to `components`, then set `[management] modelComponent = "weights"`. The Models page browses that component’s folders and files, including when its path is outside the instance directory. The same data is available through `list_model_entries` and `list_model_directories`. This needs no control server and grants no model writes. Choose either this option or the adopted `models` operation.'},{heading:`adopting-a-built-in-types-management`,content:`A type can take selected management sections from the application by adopting a built-in type:`},{heading:`adopting-a-built-in-types-management`,content:'Use `allowedMutations = []` in `[management]` to provide read-only sections, or list the writes your type supports, such as `["model.download", "extension.update"]`. This also controls the model library installer (`model.library_install`) and PyTorch reinstall (`pytorch.reinstall`). Omit the option to expose the family’s usual actions.'},{heading:`adopting-a-built-in-types-management`,content:"`adopts` names a built-in type by its id: `builtin:sd-webui`, `builtin:comfyui`, `builtin:invokeai`, `builtin:fooocus`, `builtin:sd-trainer`, `builtin:qwen-tts-webui`, `builtin:rvc-next-webui`, or `builtin:mizuoto-tts-webui`. The type needs:"},{heading:`adopting-a-built-in-types-management`,content:'`runtime = { kind = "python" }` and the `control` role: the management API serves the sections;'},{heading:`adopting-a-built-in-types-management`,content:'a `core` that is the instance\'s own. A type whose `core` is `external = "allowed"` cannot adopt, because the sections change what `core` holds.'},{heading:`adopting-a-built-in-types-management`,content:`Each operation you list adds one section to the instance's management page:`},{heading:`adopting-a-built-in-types-management`,content:`Operation`},{heading:`adopting-a-built-in-types-management`,content:`Section and what it does`},{heading:`adopting-a-built-in-types-management`,content:`What you assert about the instance`},{heading:`adopting-a-built-in-types-management`,content:"`versions`"},{heading:`adopting-a-built-in-types-management`,content:`Versions: the checkout's status, branches, and commits; switching a branch or a commit. It has no Update button`},{heading:`adopting-a-built-in-types-management`,content:"`core` is a Git checkout"},{heading:`adopting-a-built-in-types-management`,content:"`extensions`"},{heading:`adopting-a-built-in-types-management`,content:"Extensions: the adopted type's extensions (`core/extensions`, or `core/custom_nodes` for ComfyUI)"},{heading:`adopting-a-built-in-types-management`,content:"`core` is laid out as the adopted type's installation"},{heading:`adopting-a-built-in-types-management`,content:"`models`"},{heading:`adopting-a-built-in-types-management`,content:"Models: the files under `core/models` (`core/sd-models` for SD Trainer), and the adopted type's model library"},{heading:`adopting-a-built-in-types-management`,content:"`core` is laid out as the adopted type's installation"},{heading:`adopting-a-built-in-types-management`,content:"`environment`"},{heading:`adopting-a-built-in-types-management`,content:`The environment report`},{heading:`adopting-a-built-in-types-management`,content:"The instance's `python` runs your program"},{heading:`adopting-a-built-in-types-management`,content:"`pytorch`"},{heading:`adopting-a-built-in-types-management`,content:`The PyTorch catalog and reinstall`},{heading:`adopting-a-built-in-types-management`,content:"The instance's `python` runs your program"},{heading:`adopting-a-built-in-types-management`,content:"A type may adopt for `versions` and `environment` alone; those need no particular layout. Whether the adopted type supports a section follows that type: adopting `builtin:fooocus` gives no Extensions, and the section then shows as unsupported. Adopting `builtin:invokeai` gives its extensions and the environment report only: its versions, models, and PyTorch reinstall are its own package's."},{heading:`adopting-a-built-in-types-management`,content:`What stays the built-in types' own, and is refused for your type:`},{heading:`adopting-a-built-in-types-management`,content:"**The kernel update and its update summary.** Your type's `update` is its update, and an `update-check` is its check. A found update shows beside the Update action in Maintenance."},{heading:`adopting-a-built-in-types-management`,content:`**Snapshots**, including creating an instance from one.`},{heading:`adopting-a-built-in-types-management`,content:`**The hotpatch, launch arguments, and the launch checks.** Your servers start from your own commands.`},{heading:`adopting-a-built-in-types-management`,content:`**Branch variants.**`},{heading:`adopting-a-built-in-types-management`,content:`Two things to know when you write the type:`},{heading:`adopting-a-built-in-types-management`,content:"A switch to a commit leaves `core` detached. If your `update.steps` is a `git-pull`, it reports that; write the step you want for that case."},{heading:`adopting-a-built-in-types-management`,content:`The PyTorch reinstall is refused while the instance is launched. A role started from Settings → API Servers is not a launch, so stop such a role before reinstalling PyTorch.`},{heading:`adopting-a-built-in-types-management`,content:`The sample adopted-webui is a complete type of this kind.`},{heading:`discovery`,content:"The application's discovery (the instance scan, and dropping a folder on the application) recognizes the built-in WebUIs by their layouts. Your type recognizes its own installations with `[[discovery]]` signatures; a type without one is never discovered."},{heading:`discovery`,content:`At each directory the scan visits, the built-in layouts are tried first; then, outside every installation found so far, the registered types' signatures in order. A directory a signature matched is not scanned further.`},{heading:`discovery`,content:"A marker counts only when it is a regular file or directory reached without following a link. Paths are relative, `/`-separated, of ordinary names: `..`, a leading `/`, a backslash, or a drive is refused at registration."},{heading:`discovery`,content:"`components` names only components the type declares. The others are `<root>/<name>`, and every component must exist: an import adopts existing directories."},{heading:`discovery`,content:"`values` are checked against your install parameters at registration: an unknown parameter or a required one without value or default is an issue at `discovery[<index>].values`. The others take their defaults."},{heading:`discovery`,content:"A match is imported as a ready instance of your type. A directory already managed is reported, never imported twice. Values the type refuses then (for a type a backend provides, `provider.validateSpec`), or a component missing on disk, make it a warning instead of an instance."},{heading:`discovery`,content:'`external = ["core", "node"]` records those components of an attached installation as external (each declared `external = "allowed"`): deleting or reinstalling the instance never removes them.'},{heading:`discovery`,content:"`attachOnly = true` (a top-level key) makes discovery the only way to an instance, for an installation the user made, such as an npm global prefix: the creation page does not list the type, and creating or importing one by hand is refused. A type that sets it needs a signature."},{heading:`discovery`,content:`Signatures leave with your type: once the extension is turned off, its types are no longer discovered.`},{heading:`types-a-backend-provides`,content:'A type with `provider = "backend"` keeps what is static in its descriptor (id, text, components, runtime, parameters, servers, operations) and asks the extension\'s backend for the rest:'},{heading:`types-a-backend-provides`,content:"The extension must have a `[backend]`; otherwise the install fails."},{heading:`types-a-backend-provides`,content:"Declare `install.steps` (even an empty list) to supply fixed install steps. Declare `[reinstall]` to override those steps for explicit reinstalls. Declare `[update]` to supply fixed update steps. The backend plans each omitted phase. Each role may declare a static `command` or request its command from the backend."},{heading:`types-a-backend-provides`,content:"Besides `update` and `terminal`, its `operations` may name `update-check` and operations of its own, of `a-z`, `0-9`, `-`, other than the built-in types' standard ones (`launch-arguments`, `snapshots`, `hotpatch`, `diagnostics`; and `versions`, `extensions`, `models`, `environment`, `pytorch`, which it declares only by adopting a built-in type's management)."},{heading:`types-a-backend-provides`,content:"`update-check` puts its instances in the application's update check: the card's \"check for updates\" and the daily check ask the backend `provider.checkUpdate`, even while the instance runs, and an update it finds shows on the card and in Maintenance. It is not an operation of its own: the instance's management lists no button for it. Any type in an extension with a backend can declare it independently of `update`, including one with static install steps and server commands."},{heading:`types-a-backend-provides`,content:'A custom operation can accept input and ask for confirmation in the operations panel.\nUse install parameter syntax under its form. The backend receives the checked `values`;\nthe management tool `run_instance_operation` accepts the same object.\nA management list action may specify `operation = "refresh-index"` and\n`rowField = "target"` to fill the form\'s text field with the selected row ID.\nReturn `steps` for a long operation. The host executes them under exclusive\nmaintenance and returns an activity ID for tracking and cancellation.'},{heading:`types-a-backend-provides`,content:`The backend takes part through these callbacks (see Backends):`},{heading:`types-a-backend-provides`,content:`When`},{heading:`types-a-backend-provides`,content:`Callback`},{heading:`types-a-backend-provides`,content:`The backend answers`},{heading:`types-a-backend-provides`,content:`Checking the values`},{heading:`types-a-backend-provides`,content:"`provider.validateSpec`"},{heading:`types-a-backend-provides`,content:`Problems by parameter; the application runs its own form checks first`},{heading:`types-a-backend-provides`,content:`Install, retry, reinstall, update`},{heading:`types-a-backend-provides`,content:"`provider.installPlan`"},{heading:`types-a-backend-provides`,content:"A list of steps, written as `install.steps` are, placeholders and all"},{heading:`types-a-backend-provides`,content:`Starting a role`},{heading:`types-a-backend-provides`,content:"`provider.launchPlan`"},{heading:`types-a-backend-provides`,content:"`argv` and `env`, written as a server's `command` and `env`, `{port}` allowed"},{heading:`types-a-backend-provides`,content:"Checking for an update (`update-check`)"},{heading:`types-a-backend-provides`,content:"`provider.checkUpdate`"},{heading:`types-a-backend-provides`,content:`Whether an applicable update exists, and its current and latest version`},{heading:`types-a-backend-provides`,content:`Reading an instance’s select choices`},{heading:`types-a-backend-provides`,content:"`provider.launchOptions`"},{heading:`types-a-backend-provides`,content:"Values grouped by each field’s `optionsSource`"},{heading:`types-a-backend-provides`,content:`Running an operation of its own`},{heading:`types-a-backend-provides`,content:"`provider.manage.<operation>`"},{heading:`types-a-backend-provides`,content:`Optional notice and an optional maintenance step plan`},{heading:`types-a-backend-provides`,content:`The application checks a plan as it checks a descriptor's steps: an undeclared placeholder, a path that does not start in a declared component, an unknown step kind, or a value that would leave its component refuses the whole plan before anything runs. The backend names components, never paths; the application runs the steps.`},{heading:`types-a-backend-provides`,content:`Reading an existing instance's record never asks the backend, so its instances stay listed while the backend is down. While the backend fails or restarts, these types stay registered, and operations that need it fail with "extension backend unavailable". The types leave only when the extension is turned off, updated, or uninstalled.`},{heading:`presets`,content:"A preset is a set of defaults over one instance type, which the new installation page lists under that type: choosing it fills the form, and the user can still change every value. Every `.toml` or `.json` file the manifest's `contributes.presets` glob matches is one preset, whose id is `<extension id>:<id>`, such as `com.example.greeter:morning`. Its base type can be one of your extension's types, another extension's, or a built-in one."},{heading:`presets`,content:"`[install]` sets fields of the base type's install form. The user's edits take precedence. A field the preset leaves out keeps the type's default, and the user fills any remaining required fields. Leave `secret` fields for the user to enter. Naming one in a preset makes that preset unusable, and **Save as preset** omits secret fields."},{heading:`presets`,content:"`[launch.values]` sets declared nonsecret launch fields for a new instance, e.g. `threads = 4`. Changing the preset affects future instances only."},{heading:`presets`,content:"`[launch] arguments` replaces the type's default argument of the same name (`true` passes the option alone, a number or text passes it with that value, `false` removes it) and appends the others. Only built-in types take launch arguments."},{heading:`presets`,content:`The application checks a preset against its base type each time it lists it. A preset whose base type is not installed, that sets a field the form does not have, or a value the field does not take, is listed as unavailable with the reason; it never fails your extension. A file that does not read, or a malformed id, base or argument, fails the install as a type descriptor does.`},{heading:`presets`,content:`An instance keeps the preset's launch arguments as they were at creation. Editing or removing the preset leaves existing instances’ configuration intact. Their availability follows the base type. If that type belongs to the same extension, turning the extension off makes its instances unavailable until the type is registered again.`},{heading:`presets`,content:"The sample extension contributes `package/presets/morning.toml` over its own type."},{heading:`presets`,content:"The preset schema documents extension files, including their required `id`. Catalog annotations explain why a structurally valid preset may currently be unavailable. Complete examples above are read from validated source packages; install steps and network endpoints are not executed by the documentation checks."},{heading:`presets`,content:`For descriptor defaults, conditional requirements and validation stages, see the instance-type descriptor reference.`}],headings:[{id:`a-complete-example`,content:`A complete example`},{id:`top-level-keys`,content:`Top-level keys`},{id:`components`,content:`Components`},{id:`runtime`,content:`Runtime`},{id:`text`,content:`Text`},{id:`install-parameters`,content:`Install parameters`},{id:`placeholders`,content:`Placeholders`},{id:`steps`,content:`Steps`},{id:`servers`,content:`Servers`},{id:`the-management-api`,content:`The management API`},{id:`environment`,content:`Environment`},{id:`management-operations`,content:`Management operations`},{id:`read-only-model-component`,content:`Read-only model component`},{id:`adopting-a-built-in-types-management`,content:`Adopting a built-in type's management`},{id:`discovery`,content:`Discovery`},{id:`types-a-backend-provides`,content:`Types a backend provides`},{id:`presets`,content:`Presets`}]},o=[{depth:2,url:`#a-complete-example`,title:(0,r.jsx)(r.Fragment,{children:`A complete example`})},{depth:2,url:`#top-level-keys`,title:(0,r.jsx)(r.Fragment,{children:`Top-level keys`})},{depth:3,url:`#components`,title:(0,r.jsx)(r.Fragment,{children:`Components`})},{depth:3,url:`#runtime`,title:(0,r.jsx)(r.Fragment,{children:`Runtime`})},{depth:3,url:`#text`,title:(0,r.jsx)(r.Fragment,{children:`Text`})},{depth:2,url:`#install-parameters`,title:(0,r.jsx)(r.Fragment,{children:`Install parameters`})},{depth:2,url:`#placeholders`,title:(0,r.jsx)(r.Fragment,{children:`Placeholders`})},{depth:2,url:`#steps`,title:(0,r.jsx)(r.Fragment,{children:`Steps`})},{depth:2,url:`#servers`,title:(0,r.jsx)(r.Fragment,{children:`Servers`})},{depth:3,url:`#the-management-api`,title:(0,r.jsx)(r.Fragment,{children:`The management API`})},{depth:2,url:`#environment`,title:(0,r.jsx)(r.Fragment,{children:`Environment`})},{depth:2,url:`#management-operations`,title:(0,r.jsx)(r.Fragment,{children:`Management operations`})},{depth:3,url:`#read-only-model-component`,title:(0,r.jsx)(r.Fragment,{children:`Read-only model component`})},{depth:3,url:`#adopting-a-built-in-types-management`,title:(0,r.jsx)(r.Fragment,{children:`Adopting a built-in type's management`})},{depth:2,url:`#discovery`,title:(0,r.jsx)(r.Fragment,{children:`Discovery`})},{depth:2,url:`#types-a-backend-provides`,title:(0,r.jsx)(r.Fragment,{children:`Types a backend provides`})},{depth:2,url:`#presets`,title:(0,r.jsx)(r.Fragment,{children:`Presets`})}];functio